import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class PathTraversalFixed {
    public static void main(String[] args) {
        // Safe approach: Validate and resolve the path to ensure it stays within the allowed directory.
        String userInput = "../etc/passwd"; // Simulated malicious input
        String baseDirectory = "/var/www/uploads";

        try {
            // Resolve the user input relative to the base directory
            Path basePath = Paths.get(baseDirectory).toAbsolutePath().normalize();
            Path requestedPath = basePath.resolve(userInput).normalize();

            // Ensure the resolved path starts with the base directory (canonical check)
            if (!requestedPath.startsWith(basePath)) {
                throw new SecurityException("Access denied: Path traversal detected.");
            }

            // Now safe to read the file
            if (Files.exists(requestedPath)) {
                System.out.println("Safe access: " + requestedPath);
            }
        } catch (SecurityException e) {
            System.err.println(e.getMessage());
        }
    }
}
